ALTER TABLE public.maintenance_agreements ADD COLUMN title text NOT NULL DEFAULT '', ADD COLUMN contract_kind text NOT NULL DEFAULT 'maintenance', ADD COLUMN project_price numeric NOT NULL DEFAULT 0, ADD COLUMN contract_document_id uuid REFERENCES public.document_masters(id);
CREATE TABLE public.agreement_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id), agreement_id uuid NOT NULL REFERENCES public.maintenance_agreements(id), asset_id uuid NOT NULL REFERENCES public.assets(id), checklist_document_id uuid REFERENCES public.document_masters(id), schedule_document_id uuid REFERENCES public.document_masters(id), checklist_snapshot jsonb NOT NULL DEFAULT '{}', schedule_snapshot jsonb NOT NULL DEFAULT '{}', annual_price numeric NOT NULL DEFAULT 0 CHECK(annual_price>=0), pricing_snapshot jsonb NOT NULL DEFAULT '{}', start_date date NOT NULL, end_date date NOT NULL, interval_months integer NOT NULL DEFAULT 1 CHECK(interval_months IN(1,2,3,4,6,12)), renewal_history jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(agreement_id,asset_id));
GRANT SELECT,INSERT,UPDATE ON public.agreement_assets TO authenticated;
GRANT ALL ON public.agreement_assets TO service_role;
ALTER TABLE public.agreement_assets ENABLE ROW LEVEL SECURITY;
CREATE POLICY agreement_asset_read ON public.agreement_assets FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.member_commercial_can('contracts'));
CREATE POLICY agreement_asset_insert ON public.agreement_assets FOR INSERT TO authenticated WITH CHECK(company_id=public.current_company_id() AND public.member_commercial_can('contracts'));
CREATE POLICY agreement_asset_update ON public.agreement_assets FOR UPDATE TO authenticated USING(company_id=public.current_company_id() AND public.member_commercial_can('contracts')) WITH CHECK(company_id=public.current_company_id() AND public.member_commercial_can('contracts'));
CREATE TRIGGER commercial_write_guard BEFORE INSERT OR UPDATE OR DELETE ON public.agreement_assets FOR EACH ROW EXECUTE FUNCTION public.guard_commercial_write('core');
CREATE FUNCTION public.guard_agreement_asset() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.maintenance_agreements; d public.document_masters; BEGIN
IF NOT public.member_commercial_can('contracts') OR NEW.company_id IS DISTINCT FROM public.current_company_id() THEN RAISE EXCEPTION 'Contract capability required'; END IF;
SELECT * INTO a FROM public.maintenance_agreements WHERE id=NEW.agreement_id AND company_id=NEW.company_id;
IF a.id IS NULL OR a.contract_kind<>'maintenance' OR NOT EXISTS(SELECT 1 FROM public.assets WHERE id=NEW.asset_id AND company_id=NEW.company_id AND client_id=a.client_id AND (a.site_id IS NULL OR site_id=a.site_id)) THEN RAISE EXCEPTION 'Choose equipment from this contract site'; END IF;
IF NEW.end_date<=NEW.start_date THEN RAISE EXCEPTION 'Equipment expiry must be after start'; END IF;
IF TG_OP='UPDATE' THEN
IF (NEW.company_id,NEW.agreement_id,NEW.asset_id,NEW.checklist_document_id,NEW.schedule_document_id,NEW.checklist_snapshot,NEW.schedule_snapshot,NEW.annual_price,NEW.pricing_snapshot,NEW.interval_months) IS DISTINCT FROM (OLD.company_id,OLD.agreement_id,OLD.asset_id,OLD.checklist_document_id,OLD.schedule_document_id,OLD.checklist_snapshot,OLD.schedule_snapshot,OLD.annual_price,OLD.pricing_snapshot,OLD.interval_months) THEN RAISE EXCEPTION 'Agreed equipment work and prices are frozen; create a new contract to change terms'; END IF;
IF (NEW.start_date,NEW.end_date) IS DISTINCT FROM (OLD.start_date,OLD.end_date) THEN NEW.renewal_history=OLD.renewal_history||jsonb_build_array(jsonb_build_object('start',OLD.start_date,'end',OLD.end_date,'renewed_at',now(),'renewed_by',auth.uid())); ELSE NEW.renewal_history=OLD.renewal_history; END IF; RETURN NEW; END IF;
IF NEW.checklist_document_id IS NOT NULL THEN SELECT * INTO d FROM public.document_masters WHERE id=NEW.checklist_document_id AND company_id=NEW.company_id AND state='active' AND kind='checklist'; IF d.id IS NULL THEN RAISE EXCEPTION 'Choose an active company checklist'; END IF; NEW.checklist_snapshot=jsonb_build_object('name',d.name,'items',d.items,'field_specs',d.field_specs,'revision',d.revision); END IF;
IF NEW.schedule_document_id IS NOT NULL THEN SELECT * INTO d FROM public.document_masters WHERE id=NEW.schedule_document_id AND company_id=NEW.company_id AND state='active'; IF d.id IS NULL THEN RAISE EXCEPTION 'Choose an active company schedule'; END IF; NEW.schedule_snapshot=jsonb_build_object('name',d.name,'body',d.body,'items',d.items,'revision',d.revision); END IF;
IF NEW.pricing_snapshot ? 'liftPricing' AND NEW.pricing_snapshot->'liftPricing'<>'null'::jsonb AND NOT public.company_module_access(NEW.company_id,'lift_pack') THEN RAISE EXCEPTION 'Lift pricing requires the Lift pack'; END IF;
NEW.renewal_history='[]'; RETURN NEW; END $$;
CREATE TRIGGER agreement_asset_guard BEFORE INSERT OR UPDATE ON public.agreement_assets FOR EACH ROW EXECUTE FUNCTION public.guard_agreement_asset();
CREATE FUNCTION public.aggregate_agreement_assets() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.maintenance_agreements SET annual_price=(SELECT sum(annual_price) FROM public.agreement_assets WHERE agreement_id=NEW.agreement_id),start_date=(SELECT min(start_date) FROM public.agreement_assets WHERE agreement_id=NEW.agreement_id),end_date=(SELECT max(end_date) FROM public.agreement_assets WHERE agreement_id=NEW.agreement_id) WHERE id=NEW.agreement_id; RETURN NEW; END $$;
CREATE TRIGGER aggregate_agreement_assets AFTER INSERT OR UPDATE ON public.agreement_assets FOR EACH ROW EXECUTE FUNCTION public.aggregate_agreement_assets();
CREATE FUNCTION public.guard_agreement_header() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.document_masters; BEGIN
IF NEW.contract_kind NOT IN('maintenance','installation') OR NEW.project_price<0 OR NEW.end_date<=NEW.start_date THEN RAISE EXCEPTION 'Invalid contract type, dates or price'; END IF;
IF NEW.site_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sites WHERE id=NEW.site_id AND client_id=NEW.client_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Choose a site belonging to the client'; END IF;
IF NEW.contract_document_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.contract_document_id IS DISTINCT FROM OLD.contract_document_id) THEN SELECT * INTO d FROM public.document_masters WHERE id=NEW.contract_document_id AND company_id=NEW.company_id AND state='active' AND kind='contract'; IF d.id IS NULL THEN RAISE EXCEPTION 'Choose an active company contract document'; END IF; NEW.terms_snapshot=NEW.terms_snapshot||jsonb_build_object('contract',jsonb_build_object('name',d.name,'body',d.body,'items',d.items,'revision',d.revision)); END IF;
IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.agreement_assets WHERE agreement_id=NEW.id) THEN IF (NEW.client_id,NEW.site_id,NEW.contract_kind,NEW.contract_document_id,NEW.terms_snapshot) IS DISTINCT FROM (OLD.client_id,OLD.site_id,OLD.contract_kind,OLD.contract_document_id,OLD.terms_snapshot) THEN RAISE EXCEPTION 'Covered contract identity and signed terms cannot change'; END IF; SELECT sum(annual_price),min(start_date),max(end_date) INTO NEW.annual_price,NEW.start_date,NEW.end_date FROM public.agreement_assets WHERE agreement_id=NEW.id; END IF; RETURN NEW; END $$;
CREATE TRIGGER zz_agreement_header_guard BEFORE INSERT OR UPDATE ON public.maintenance_agreements FOR EACH ROW EXECUTE FUNCTION public.guard_agreement_header();
CREATE FUNCTION public.save_equipment_contract(_header jsonb,_lines jsonb,_agreement uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE a uuid; c uuid=public.current_company_id(); l jsonb; BEGIN
IF NOT public.member_commercial_can('contracts') OR NOT public.company_module_access(c,'core') THEN RAISE EXCEPTION 'Core contract access required'; END IF;
IF jsonb_typeof(_lines)<>'array' OR jsonb_array_length(_lines)>100 THEN RAISE EXCEPTION 'Provide at most 100 covered assets'; END IF;
IF _agreement IS NULL THEN IF coalesce(_header->>'kind','maintenance')='maintenance' AND jsonb_array_length(_lines)=0 THEN RAISE EXCEPTION 'Select at least one covered equipment'; END IF;
INSERT INTO public.maintenance_agreements(company_id,client_id,site_id,title,contract_kind,contract_document_id,contract_type_id,start_date,end_date,annual_price,project_price,notes) VALUES(c,(_header->>'client_id')::uuid,nullif(_header->>'site_id','')::uuid,coalesce(_header->>'title',''),coalesce(_header->>'kind','maintenance'),nullif(_header->>'document_id','')::uuid,nullif(_header->>'tier_id','')::uuid,(_header->>'start')::date,(_header->>'end')::date,coalesce((_header->>'price')::numeric,0),coalesce((_header->>'price')::numeric,0),coalesce(_header->>'notes','')) RETURNING id INTO a;
ELSE SELECT id INTO a FROM public.maintenance_agreements WHERE id=_agreement AND company_id=c AND contract_kind='maintenance' AND status='active' FOR UPDATE; IF a IS NULL THEN RAISE EXCEPTION 'Active contract unavailable'; END IF; END IF;
FOR l IN SELECT value FROM jsonb_array_elements(_lines) LOOP INSERT INTO public.agreement_assets(company_id,agreement_id,asset_id,checklist_document_id,schedule_document_id,annual_price,pricing_snapshot,start_date,end_date,interval_months) VALUES(c,a,(l->>'asset_id')::uuid,nullif(l->>'checklist_id','')::uuid,nullif(l->>'schedule_id','')::uuid,(l->>'price')::numeric,coalesce(l->'pricing','{}'),(l->>'start')::date,(l->>'end')::date,(l->>'months')::integer); END LOOP; RETURN a; END $$;
REVOKE ALL ON FUNCTION public.save_equipment_contract(jsonb,jsonb,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_equipment_contract(jsonb,jsonb,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.capture_sheet_requirements() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.maintenance_agreements; items text[]; selected jsonb; plan uuid; at_date date; BEGIN
IF TG_OP='INSERT' THEN SELECT coalesce(array_agg(item),'{}') INTO NEW.safety_snapshot FROM public.safety_templates t CROSS JOIN LATERAL unnest(t.items) item WHERE t.company_id=NEW.company_id AND t.enabled; ELSE NEW.safety_snapshot=OLD.safety_snapshot; NEW.checklist_snapshot=OLD.checklist_snapshot; END IF;
IF NEW.is_maintenance AND (TG_OP='INSERT' OR NOT OLD.is_maintenance OR (OLD.status<>'completed' AND (OLD.asset_id IS DISTINCT FROM NEW.asset_id OR OLD.job_id IS DISTINCT FROM NEW.job_id OR OLD.client_id IS DISTINCT FROM NEW.client_id OR OLD.site_id IS DISTINCT FROM NEW.site_id OR OLD.asset_type IS DISTINCT FROM NEW.asset_type))) THEN
SELECT ppm_plan_id,coalesce(ppm_due_date,scheduled_date) INTO plan,at_date FROM public.jobs WHERE id=NEW.job_id AND company_id=NEW.company_id; at_date=coalesce(at_date,current_date);
SELECT x.checklist_snapshot INTO selected FROM public.agreement_assets x JOIN public.maintenance_agreements h ON h.id=x.agreement_id WHERE x.company_id=NEW.company_id AND x.asset_id=NEW.asset_id AND h.status='active' AND (x.start_date<=at_date AND x.end_date>=at_date OR EXISTS(SELECT 1 FROM jsonb_array_elements(x.renewal_history) z WHERE (z->>'start')::date<=at_date AND (z->>'end')::date>=at_date)) AND (plan IS NULL OR x.agreement_id=(SELECT agreement_id FROM public.ppm_plans WHERE id=plan)) ORDER BY x.created_at DESC LIMIT 1;
SELECT coalesce(array_agg(v),'{}') INTO items FROM jsonb_array_elements_text(coalesce(selected->'items','[]')) WITH ORDINALITY t(v,n) WHERE coalesce(selected->'field_specs'->(n::integer-1)->>'audience','both')<>'client';
IF cardinality(items)=0 THEN SELECT * INTO a FROM public.maintenance_agreements WHERE company_id=NEW.company_id AND client_id=NEW.client_id AND status='active' AND start_date<=at_date AND end_date>=at_date AND (site_id=NEW.site_id OR site_id IS NULL) AND NOT EXISTS(SELECT 1 FROM public.agreement_assets WHERE agreement_id=maintenance_agreements.id) ORDER BY site_id NULLS LAST,created_at DESC LIMIT 1; SELECT coalesce(array_agg(value),'{}') INTO items FROM jsonb_array_elements_text(coalesce(a.terms_snapshot->'checklist'->'items','[]')) value; END IF;
IF cardinality(items)=0 THEN SELECT coalesce(array_agg(value),'{}') INTO items FROM public.checklist_templates t CROSS JOIN LATERAL jsonb_array_elements_text(t.items) value WHERE t.company_id=NEW.company_id AND t.id=(SELECT id FROM public.checklist_templates WHERE company_id=NEW.company_id AND equipment_category=CASE NEW.asset_type WHEN 'Lift' THEN 'Elevator' WHEN 'Escalator' THEN 'Escalator' ELSE coalesce(NEW.asset_type_other,'Custom') END ORDER BY created_at DESC LIMIT 1); END IF; NEW.checklist_snapshot=coalesce(items,'{}'); END IF; RETURN NEW; END $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.generate_ppm_visits(uuid)'::regprocedure) INTO d; d=replace(d,'IF NOT p.active OR a.status<>''active'' THEN RETURN 0; END IF;', 'SELECT x.start_date,x.end_date INTO a.start_date,a.end_date FROM public.agreement_assets x WHERE x.agreement_id=p.agreement_id AND x.asset_id=p.asset_id; IF NOT FOUND THEN SELECT * INTO a FROM public.maintenance_agreements WHERE id=p.agreement_id; END IF; IF NOT p.active OR a.status<>''active'' THEN RETURN 0; END IF;'); EXECUTE d; END $$;
CREATE FUNCTION public.guard_ppm_equipment_dates() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x public.agreement_assets; BEGIN IF EXISTS(SELECT 1 FROM public.agreement_assets WHERE agreement_id=NEW.agreement_id) THEN SELECT * INTO x FROM public.agreement_assets WHERE agreement_id=NEW.agreement_id AND asset_id=NEW.asset_id AND company_id=NEW.company_id; IF x.id IS NULL OR NEW.first_due_date<x.start_date OR NEW.first_due_date>x.end_date OR NEW.interval_months<>x.interval_months THEN RAISE EXCEPTION 'Maintenance schedule must match this covered equipment and its dates'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER zz_ppm_equipment_dates BEFORE INSERT OR UPDATE ON public.ppm_plans FOR EACH ROW EXECUTE FUNCTION public.guard_ppm_equipment_dates();
CREATE FUNCTION public.client_contract_coverage(_client uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s jsonb=public.client_workspace_scope(_client); result jsonb; BEGIN IF NOT public.company_module_access((SELECT company_id FROM public.clients WHERE id=_client),'client_portal') THEN RAISE EXCEPTION 'Client portal access required'; END IF;
SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'kind',a.contract_kind,'site_id',a.site_id,'status',a.status,'start',a.start_date,'end',a.end_date,'price',a.annual_price,'terms',a.terms_snapshot->'contract','assets',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'reference',e.reference_number,'start',x.start_date,'end',x.end_date,'price',x.annual_price,'months',x.interval_months,'checklist',x.checklist_snapshot->>'name','items',(SELECT coalesce(jsonb_agg(v),'[]') FROM jsonb_array_elements_text(coalesce(x.checklist_snapshot->'items','[]')) WITH ORDINALITY t(v,n) WHERE coalesce(x.checklist_snapshot->'field_specs'->(n::integer-1)->>'audience','both')<>'technician'),'schedule',x.schedule_snapshot) ORDER BY e.reference_number),'[]') FROM public.agreement_assets x JOIN public.assets e ON e.id=x.asset_id WHERE x.agreement_id=a.id))), '[]') INTO result FROM public.maintenance_agreements a WHERE a.client_id=_client AND a.company_id=(SELECT company_id FROM public.clients WHERE id=_client) AND (coalesce((s->>'office')::boolean,false) OR coalesce((s->>'all_sites')::boolean,false) OR (a.site_id IS NOT NULL AND to_jsonb(a.site_id::text)<@coalesce(s->'site_ids','[]'))); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.client_contract_coverage(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.client_contract_coverage(uuid) TO authenticated;